// Extraer parámetros del webhook
// El webhook debe recibir: { "text": "Texto del post", "token": "Bearer token de LinkedIn" }
// O solo { "text": "..." } si el token está en las credenciales de n8n

const body = $input.first().json.body || $input.first().json;

const postText = body.text || body.texto || body.contenido || 'Publicación de prueba desde Zyndrix Agency 🚀\n\n#automation #n8n #zyndrix';
const bearerToken = body.token || body.access_token || '';
const visibility = body.visibility || 'PUBLIC';

if (!postText || postText.trim().length === 0) {
  throw new Error('El texto del post no puede estar vacío. Envía { "text": "Tu mensaje" }');
}

if (postText.length > 3000) {
  throw new Error('El texto supera los 3000 caracteres permitidos por LinkedIn.');
}

return [{
  json: {
    postText: postText.trim(),
    bearerToken,
    visibility
  }
}];

// Intentar obtener el personId desde cualquiera de los dos nodos anteriores
let profileData = null;
let personId = null;
let source = '';

try {
  const oauthResult = $('Get Profile (OAuth2)').first();
  if (oauthResult && oauthResult.json) {
    const data = oauthResult.json.body || oauthResult.json;
    if (data.sub) {
      personId = data.sub;
      source = 'OAuth2 - userinfo.sub';
    }
  }
} catch(e) {}

if (!personId) {
  try {
    const manualResult = $('Get Profile (Token Manual)').first();
    if (manualResult && manualResult.json) {
      const data = manualResult.json.body || manualResult.json;
      if (data.sub) {
        personId = data.sub;
        source = 'Token Manual - userinfo.sub';
      }
    }
  } catch(e) {}
}

if (!personId) {
  throw new Error(
    'No se pudo obtener el Person ID de LinkedIn.\n\n' +
    'CAUSAS POSIBLES:\n' +
    '1. Token sin scope "openid" o "profile"\n' +
    '2. Credencial LinkedIn OAuth2 no configurada en n8n\n' +
    '3. Token expirado o inválido\n\n' +
    'SOLUCIÓN: Verifica que tu LinkedIn App tenga los scopes: openid, profile, w_member_social'
  );
}

const params = $('Extract & Validate Params').first().json;

return [{
  json: {
    personId,
    source,
    postText: params.postText,
    visibility: params.visibility,
    bearerToken: params.bearerToken
  }
}];

const { personId, postText, visibility, bearerToken } = $input.first().json;

// Construir el body para LinkedIn UGC Posts API v2
const ugcBody = {
  author: `urn:li:person:${personId}`,
  lifecycleState: 'PUBLISHED',
  specificContent: {
    'com.linkedin.ugc.ShareContent': {
      shareCommentary: {
        text: postText
      },
      shareMediaCategory: 'NONE'
    }
  },
  visibility: {
    'com.linkedin.ugc.MemberNetworkVisibility': visibility
  }
};

return [{
  json: {
    ugcBody,
    ugcBodyStr: JSON.stringify(ugcBody),
    personId,
    bearerToken
  }
}];

// Evaluar resultado de ambas opciones de publicación
let result = null;
let error = null;
let statusCode = null;
let postId = null;

try {
  const oauthResult = $('Post LinkedIn (OAuth2)').first();
  if (oauthResult && oauthResult.json) {
    statusCode = oauthResult.json.statusCode;
    if (statusCode === 201 || statusCode === 200) {
      postId = oauthResult.json.headers?.['x-restli-id'] || oauthResult.json.headers?.['X-RestLi-Id'];
      result = { method: 'OAuth2', postId, status: 'published' };
    } else {
      error = { method: 'OAuth2', statusCode, body: oauthResult.json.body };
    }
  }
} catch(e) {}

if (!result) {
  try {
    const manualResult = $('Post LinkedIn (Token Manual)').first();
    if (manualResult && manualResult.json) {
      statusCode = manualResult.json.statusCode;
      if (statusCode === 201 || statusCode === 200) {
        postId = manualResult.json.headers?.['x-restli-id'] || manualResult.json.headers?.['X-RestLi-Id'];
        result = { method: 'Token Manual', postId, status: 'published' };
      } else {
        error = { method: 'Token Manual', statusCode, body: manualResult.json.body };
      }
    }
  } catch(e) {}
}

if (result) {
  return [{ json: { success: true, ...result } }];
} else {
  return [{ json: {
    success: false,
    error: error || 'No se pudo publicar en LinkedIn',
    diagnostico: [
      '401 → Token inválido o expirado',
      '403 → Sin permiso. Scope w_member_social requerido. Verifica en LinkedIn Developer Portal',
      '422 → Body mal formateado o personId incorrecto',
      '429 → Rate limit de LinkedIn (máx 150 req/día para ugcPosts)'
    ]
  }}];
}
